                        raise ValueError("Misplaced 'then'")

                    # The current top of instruction_lists is the list we just finished (either else or then)
                    current_list = instruction_lists.pop()

                    if ctx['else_list'] is not None:
                        # We had an else branch. current_list should be the else list.
                        if current_list is not ctx['else_list']:
                             raise ValueError("Logic error in parsing")
                        # Pop the then list which is now at the top
                        then_list = instruction_lists.pop()
                        if then_list is not ctx['then_list']:
                             raise ValueError("Logic error in parsing")
                        instr = ('if', then_list, current_list)
                    else:
                        # No else branch. current_list should be the then list.
                        if current_list is not ctx['then_list']:
                             raise ValueError("Logic error in parsing")
                        # No need to pop another list, then_list was the one we just popped
                        then_list = current_list
                        instr = ('if', then_list, [])

                    if not instruction_lists:
                        raise ValueError("Unbalanced control words")
                    # Append the if instruction to the list that was active before the if started
                    instruction_lists[-1].append(instr)

                elif tok == 'begin':
                    # Push a new list for the loop body
                    instruction_lists.append([])
                    constructors.append({'type': 'begin', 'body': instruction_lists[-1]})
                elif tok == 'until':
                    if not constructors or constructors[-1]['type'] != 'begin':
                        raise ValueError("Misplaced 'until'")
                    ctx = constructors.pop()
                    # Current list is the loop body
                    current_list = instruction_lists.pop()
                    if current_list is not ctx['body']:
                        raise ValueError("Logic error in parsing")
                    instr = ('begin', current_list)
                    if not instruction_lists:
                        raise ValueError("Unbalanced control words")
                    instruction_lists[-1].append(instr)
                else:
                    resolved = resolve_word(tok)
                    instruction_lists[-1].append(resolved)

                i += 1

            if i >= n:
                raise ValueError("Missing ';'")
            if len(instruction_lists) > 1:
                raise ValueError("Unbalanced control words")

            defs[name] = instruction_lists[0]

        elif tok in control_words:
            raise ValueError("Control word outside body")
        elif tok == ';':
            raise ValueError("';' outside body")
        else:
            resolved = resolve_word(tok)
            if resolved[0] == 'lit':
                stack.append(resolved[1])
            else:
                target = resolved[1]
                if isinstance(target, list):
                    execute(target, stack)
                else:
                    target(stack)
            i += 1

    return stack

