def mod_sqrts(a: int, m: int) -> list[int]:
    """
    Returns a sorted list of all integers x such that 0 <= x < m and x*x == a (mod m).
    """
    if m < 1:
        raise ValueError("Modulus m must be >= 1")
    if m == 1:
        return [0]

    a = a % m

    # Factorize m into prime powers
    factors = []
    d = 2
    temp = m
    while d * d <= temp:
        if temp % d == 0:
            e = 0
            while temp % d == 0:
                e += 1
                temp //= d
            factors.append((d, e))
        d += 1
    if temp > 1:
        factors.append((temp, 1))

    # Solve for each prime power and combine using CRT
    # Store roots as (remainder, modulus) tuples
    all_roots = [(0, 1)]
    current_mod = 1

    for p, e in factors:
        p_pow = p ** e
        roots_p = _solve_prime_power(a, p, e)
        if not roots_p:
            return []

        # Combine with existing roots using CRT
        new_roots = []
        # Precompute inverse for CRT: current_mod^{-1} mod p_pow
        # Since p is a new prime factor, gcd(current_mod, p_pow) = 1
        try:
            inv = pow(current_mod, -1, p_pow)
        except ValueError:
            return []

        for rem1, mod1 in all_roots:
            for r2 in roots_p:
                # We want x = rem1 + mod1 * k such that x = r2 (mod p_pow)
                # rem1 + mod1 * k = r2 (mod p_pow)
                # mod1 * k = r2 - rem1 (mod p_pow)
                # k = (r2 - rem1) * inv (mod p_pow)
                k = ((r2 - rem1) * inv) % p_pow
                new_r = rem1 + mod1 * k
                new_roots.append((new_r, mod1 * p_pow))

        all_roots = new_roots
        current_mod *= p_pow

    return sorted([r[0] for r in all_roots])

def _solve_prime_power(a: int, p: int, e: int) -> list[int]:
    """Solves x^2 = a (mod p^e)"""
    n = p ** e
    a = a % n

    if p == 2:
        return _solve_mod_2pow(a, e)
    else:
        return _solve_mod_odd_prime_power(a, p, e)

def _solve_mod_2pow(a: int, e: int) -> list[int]:
    """Solves x^2 = a (mod 2^e)"""
    if e == 1:
        return [a % 2]

    if e == 2:
        if a % 4 == 0: return [0, 2]
        if a % 4 == 1: return [1, 3]
        return []

    # e >= 3
    # Check if a is a quadratic residue mod 8 if a is odd
    if a % 2 != 0:
        if a % 8 != 1:
            return []
        # Find one root using Hensel lifting from mod 8 to mod 2^e
        # Start with root x=1 mod 8 (since 1^2 = 1 = a mod 8)
        x = 1

        # Lift from 2^k to 2^{k+1} for k = 3 to e-1
        # We maintain x such that x^2 = a mod 2^k
        # We want to find t in {0, 1} such that (x + t*2^{k-1})^2 = a mod 2^{k+1}
        # (x + t*2^{k-1})^2 = x^2 + t*x*2^k + t^2*2^{2k-2}
        # Since k >= 3, 2k-2 >= k+1, so t^2 term vanishes mod 2^{k+1}
        # We need x^2 + t*x*2^k = a mod 2^{k+1}
        # t*x*2^k = a - x^2 mod 2^{k+1}
        # t*x = (a - x^2)/2^k mod 2
        # Since x is odd, x^{-1} mod 2 is 1.
        # t = (a - x^2)/2^k mod 2

        for k in range(3, e):
            # x is root mod 2^k. Check bit k of (a - x^2).
            # (a - x^2) must be divisible by 2^k.
            diff = (a - x * x) >> k
            t = diff & 1
            x += t << (k - 1)

        # Now x is a root mod 2^e.
        # The roots come in pairs x and -x, and also x + 2^{e-1} and -x + 2^{e-1}
        # Actually for 2^e (e>=3), there are 4 roots: x, -x, x+2^{e-1}, -x+2^{e-1}
        n = 1 << e
        r1 = x
        r2 = n - x
        r3 = (x + (1 << (e - 1))) % n
        r4 = (n - x + (1 << (e - 1))) % n

        roots = sorted({r1, r2, r3, r4})
        return roots
    else:
        # a is even. Let a = 2^k * u where u is odd.
        # If k is odd, no solution.
        # If k >= e, x^2 = 0 mod 2^e => x is multiple of 2^{ceil(e/2)}
        # If k < e and k is even (k=2j), then x = 2^j * y, y^2 = u mod 2^{e-2j}.

        # Count factors of 2 in a
        if a == 0:
            k = e
        else:
            k = 0
            temp = a
            while temp % 2 == 0:
                k += 1
                temp //= 2

        if k % 2 != 0:
            return []

        if k >= e:
            # x^2 = 0 mod 2^e
            limit = 1 << ((e + 1) // 2)
            return list(range(0, 1 << e, limit))

        # k < e and k is even
        j = k // 2
        rem_e = e - k
        u = a >> k # a / 2^k

        # Solve y^2 = u mod 2^rem_e
        # u is odd
        roots_y = _solve_mod_2pow(u, rem_e)
        if not roots_y:
            return []

        shift = 1 << j
        step = 1 << (e - j)
        res = []
        for r in roots_y:
            base = (r * shift) % (1 << e)
            for i in range(0, (1 << e), step):
                res.append((base + i) % (1 << e))
        return sorted(res)

def _solve_mod_odd_prime_power(a: int, p: int, e: int) -> list[int]:
    """Solves x^2 = a (mod p^e) for odd prime p"""
    n = p ** e

    # Check if a is divisible by p
    if a % p == 0:
        # x^2 = 0 mod p^e implies x is multiple of p^ceil(e/2)
        # More generally, if a = p^k * u with p not dividing u.
        # If k is odd, no solution.
        # If k is even, x = p^{k/2} * y, y^2 = u mod p^{e-k}.

        k = 0
        temp = a
        while temp % p == 0:
            k += 1
            temp //= p

        if k % 2 != 0:
            return []

        half_k = k // 2
        rem_e = e - k

        if rem_e <= 0:
            # a = 0 mod p^e
            # x^2 = 0 mod p^e => x is multiple of p^ceil(e/2)
            limit = p ** ((e + 1) // 2)
            return list(range(0, p**e, limit))

        # Recursive step
        roots_y = _solve_mod_odd_prime_power(temp, p, rem_e)
        if not roots_y:
            return []

        shift = p ** half_k
        step = p ** (e - half_k)
        res = []
        for r in roots_y:
            base = (r * shift) % (p**e)
            for i in range(0, p**e, step):
                res.append((base + i) % (p**e))
        return sorted(res)

    # a is coprime to p
    # Solve x^2 = a mod p using Tonelli-Shanks
    roots_p = tonelli_shanks(a, p)
    if not roots_p:
        return []

    # Lift roots to mod p^e
    all_roots = []
    for r in roots_p:
        roots_lifted = hensel_lift(r, a, p, e)
        all_roots.extend(roots_lifted)

    return sorted(all_roots)

def tonelli_shanks(n: int, p: int) -> list[int]:
    """Returns list of solutions to x^2 = n mod p, or empty list."""
    n = n % p
    if n == 0:
        return [0]
    if p == 2:
        return [n]

    # Check Legendre symbol
    if pow(n, (p - 1) // 2, p) != 1:
        return []

    # Factor p-1 = Q * 2^S
    Q = p - 1
    S = 0
    while Q % 2 == 0:
        Q //= 2
        S += 1

    # Find quadratic non-residue z
    z = 2
    while pow(z, (p - 1) // 2, p) != p - 1:
        z += 1

    M = S
    c = pow(z, Q, p)
    t = pow(n, Q, p)
    R = pow(n, (Q + 1) // 2, p)

    while True:
        if t == 1:
            return [R, p - R]

        # Find smallest i, 0 < i < M, such that t^{2^i} = 1
        i = 1
        temp = t
        while i < M:
            temp = pow(temp, 2, p)
            if temp == 1:
                break
            i += 1

        if i == M:
            return []

        # b = c^{2^{M-i-1}}
        b = pow(c, 1 << (M - i - 1), p)
        M = i
        c = pow(b, 2, p)
        t = (t * c) % p
        R = (R * b) % p

def hensel_lift(x0: int, a: int, p: int, e: int) -> list[int]:
    """Lifts solution x0 of x^2 = a mod p to mod p^e"""
    x = x0
    for k in range(1, e):
        # We have x^2 = a mod p^k
        # We want x_new = x + t * p^k mod p^{k+1}
        # (x + t p^k)^2 = x^2 + 2 x t p^k + t^2 p^{2k}
        # 2k >= k+1 for k >= 1.
        # So x^2 + 2 x t p^k = a mod p^{k+1}
        # 2 x t p^k = a - x^2 mod p^{k+1}
        # t = (a - x^2) / (2 x p^k) mod p

        # Compute numerator (a - x^2) / p^k
        num = (a - x * x) // (p ** k)

        # Denominator is 2*x mod p. Since x is root mod p, x != 0 mod p.
        inv_2x = pow((2 * x) % p, -1, p)
        t = (num * inv_2x) % p
        x += t * (p ** k)

    return [x % (p ** e)]

