            x = pow(x, 2, n)
            if x == n - 1:
                break
        else:
            return False
    return True

def _solve_prime_power(a: int, p: int, e: int) -> list[int]:
    """Solves x^2 = a (mod p^e)"""
    n = p ** e
    a = a % n

    if p == 2:
        return _solve_mod_2pow(a, e)
    else:
        return _solve_mod_odd_prime_power(a, p, e)

def _solve_mod_2pow(a: int, e: int) -> list[int]:
    """Solves x^2 = a (mod 2^e)"""
    if e == 1:
        return [a % 2]

    if e == 2:
        rem = a % 4
        if rem == 0: return [0, 2]
        if rem == 1: return [1, 3]
        return []

    # e >= 3
    if a % 2 != 0:
        # a is odd
        if a % 8 != 1:
            return []

        # Find one root mod 8. 1^2 = 1.
        x = 1

        # Lift from 2^k to 2^{k+1} for k = 3 to e-1
        for k in range(3, e):
            # x is root mod 2^k.
            # We want x' = x + t * 2^{k-1} mod 2^{k+1}
            # (x + t 2^{k-1})^2 = x^2 + t x 2^k + t^2 2^{2k-2}
            # Since k >= 3, 2k-2 >= k+1, so t^2 term vanishes mod 2^{k+1}
            # We need x^2 + t x 2^k = a mod 2^{k+1}
            # t x 2^k = a - x^2 mod 2^{k+1}
            # t x = (a - x^2) / 2^k mod 2
            # Since x is odd, x^{-1} mod 2 is 1.
            # t = (a - x^2) / 2^k mod 2

            diff = (a - x * x) >> k
            t = diff & 1
            x += t << (k - 1)

        # Now x is a root mod 2^e.
        # The roots come in 4 pairs: x, -x, x+2^{e-1}, -x+2^{e-1}
        n = 1 << e
        r1 = x
        r2 = n - x
        r3 = (x + (1 << (e - 1))) % n
        r4 = (n - x + (1 << (e - 1))) % n

        return sorted({r1, r2, r3, r4})
    else:
        # a is even
        if a == 0:
            # x^2 = 0 mod 2^e => x is multiple of 2^{ceil(e/2)}
            limit = 1 << ((e + 1) // 2)
            return list(range(0, 1 << e, limit))

        # a = 2^k * u where u is odd
        k = 0
        temp = a
        while temp % 2 == 0:
            k += 1
            temp //= 2

        if k % 2 != 0:
            return []

        if k >= e:
            # a is 0 mod 2^e, handled above
            limit = 1 << ((e + 1) // 2)
            return list(range(0, 1 << e, limit))

        # k < e and k is even
        j = k // 2
        rem_e = e - k
        u = temp # a / 2^k

        # Solve y^2 = u mod 2^rem_e
        # u is odd
        roots_y = _solve_mod_2pow(u, rem_e)
        if not roots_y:
            return []

        shift = 1 << j
        res = []

        # For each root y modulo 2^rem_e, we get 2^j roots modulo 2^e
        # x = y * 2^j + t * 2^{e - k + j} for t in 0..2^j - 1
        # Note: e - k + j = e - k + k/2 = e - k/2
        step = 1 << (e - k + j)

        for r in roots_y:
            base = (r * shift) % (1 << e)
            # Generate lifts
            for t in range(1 << j):
                res.append((base + t * step) % (1 << e))

        return sorted(list(set(res)))

def _solve_mod_odd_prime_power(a: int, p: int, e: int) -> list[int]:
    """Solves x^2 = a (mod p^e) for odd prime p"""
    n = p ** e

    # Check if a is divisible by p
    if a % p == 0:
        # a = p^k * u with p not dividing u
        if a == 0:
            k = e
            u = 1
        else:
            k = 0
            temp = a
            while temp % p == 0:
                k += 1
                temp //= p
            u = temp

        if k % 2 != 0:
            return []

        half_k = k // 2
        rem_e = e - k

        if rem_e <= 0:
            # a = 0 mod p^e
            # x^2 = 0 mod p^e => x is multiple of p^ceil(e/2)
            limit = p ** ((e + 1) // 2)
            return list(range(0, p**e, limit))

        # Recursive step
        roots_y = _solve_mod_odd_prime_power(u, p, rem_e)
        if not roots_y:
            return []

        shift = p ** half_k
        res = []
        for r in roots_y:
            base = (r * shift) % (p**e)
            res.append(base)
        return sorted(res)

    # a is coprime to p
    # Solve x^2 = a mod p using Tonelli-Shanks
    roots_p = tonelli_shanks(a, p)
    if not roots_p:
        return []

    # Lift roots to mod p^e
    all_roots = []
    for r in roots_p:
        roots_lifted = hensel_lift(r, a, p, e)
        all_roots.extend(roots_lifted)

    return sorted(all_roots)

def tonelli_shanks(n: int, p: int) -> list[int]:
    """Returns list of solutions to x^2 = n mod p, or empty list."""
    n = n % p
    if n == 0:
        return [0]
    if p == 2:
        return [n]

    # Check Legendre symbol
    if pow(n, (p - 1) // 2, p) != 1:
        return []

    # Factor p-1 = Q * 2^S
    Q = p - 1
    S = 0
    while Q % 2 == 0:
        Q //= 2
        S += 1

    # Find quadratic non-residue z
    z = 2
    while pow(z, (p - 1) // 2, p) != p - 1:
        z += 1

    M = S
    c = pow(z, Q, p)
    t = pow(n, Q, p)
    R = pow(n, (Q + 1) // 2, p)

    while True:
        if t == 1:
            return [R, p - R]

        # Find smallest i, 0 < i < M, such that t^{2^i} = 1
        i = 1
        temp = t
        while i < M:
            temp = pow(temp, 2, p)
            if temp == 1:
                break
            i += 1

        if i == M:
            return []

        # b = c^{2^{M-i-1}}
        b = pow(c, 1 << (M - i - 1), p)
        M = i
        c = pow(b, 2, p)
        t = (t * c) % p
        R = (R * b) % p

def hensel_lift(x0: int, a: int, p: int, e: int) -> list[int]:
    """Lifts solution x0 of x^2 = a mod p to mod p^e"""
    x = x0
    # x is root mod p^1
    for k in range(1, e):
        # We have x^2 = a mod p^k
        # We want x_new = x + t * p^k mod p^{k+1}
        # (x + t p^k)^2 = x^2 + 2 x t p^k + t^2 p^{2k}
        # 2k >= k+1 for k >= 1.
        # So x^2 + 2 x t p^k = a mod p^{k+1}
        # 2 x t p^k = a - x^2 mod p^{k+1}
        # t = (a - x^2) / (2 x p^k) mod p

        # Compute numerator (a - x^2) / p^k
        num = (a - x * x) // (p ** k)

        # Denominator is 2*x mod p. Since x is root mod p, x != 0 mod p.
        inv_2x = pow((2 * x) % p, -1, p)
        t = (num * inv_2x) % p
        x += t * (p ** k)

    return [x % (p ** e)]

import math

def mod_sqrts(a: int, m: int) -> list[int]:
    """
    Returns a sorted list of all integers x such that 0 <= x < m and x*x == a (mod m).
    """
    if m < 1:
        raise ValueError("Modulus m must be >= 1")
    if m == 1:
        return [0]

    a = a % m

    # Factorize m into prime powers
    factors = []
    temp = m

    # Optimization: check if m is prime first to avoid slow trial division
    if is_prime(m):
        factors.append((m, 1))
    else:
        # Factor out 2
        if temp % 2 == 0:
            e = 0
            while temp % 2 == 0:
                e += 1
                temp //= 2
            factors.append((2, e))

        # Factor out odd primes
        d = 3
        while d * d <= temp:
            if temp % d == 0:
                e = 0
                while temp % d == 0:
                    e += 1
                    temp //= d
                factors.append((d, e))
            d += 2

        if temp > 1:
            factors.append((temp, 1))

    # Solve for each prime power and combine using CRT
    current_roots = [0]
    current_mod = 1

    for p, e in factors:
        p_pow = p ** e
        roots_p = _solve_prime_power(a, p, e)
        if not roots_p:
            return []

        # Combine with existing roots using CRT
        try:
            inv = pow(current_mod, -1, p_pow)
        except ValueError:
            return []

        new_roots = []
        for r_curr in current_roots:
            for r_p in roots_p:
                diff = (r_p - r_curr) % p_pow
                k = (diff * inv) % p_pow
                new_r = r_curr + k * current_mod
                new_roots.append(new_r)

        current_roots = new_roots
        current_mod *= p_pow

    return sorted(current_roots)

def is_prime(n: int) -> bool:
    """Miller-Rabin primality test for n < 4,759,123,141."""
    if n < 2: return False
    if n == 2 or n == 3: return True
    if n % 2 == 0 or n % 3 == 0: return False

    d = n - 1
    s = 0
    while d % 2 == 0:
        d //= 2
        s += 1

    for a_test in [2, 7, 61]:
        if n <= a_test: break
        x = pow(a_test, d, n)
        if x == 1 or x == n - 1:
            continue
        for _ in range(s - 1):
            x = pow(x, 2, n)
            if x == n - 1:
                break
        else:
            return False
    return True

def _solve_prime_power(a: int, p: int, e: int) -> list[int]:
    """Solves x^2 = a (mod p^e)"""
    n = p ** e
    a = a % n

    if p == 2:
        return _solve_mod_2pow(a, e)
    else:
        return _solve_mod_odd_prime_power(a, p, e)

def _solve_mod_2pow(a: int, e: int) -> list[int]:
    """Solves x^2 = a (mod 2^e)"""
    if e == 1:
        return [a % 2]

    if e == 2:
        rem = a % 4
        if rem == 0: return [0, 2]
        if rem == 1: return [1, 3]
        return []

    # e >= 3
    if a % 2 != 0:
        # a is odd
        if a % 8 != 1:
            return []

        # Find one root mod 8. 1^2 = 1.
        x = 1

        # Lift from 2^k to 2^{k+1} for k = 3 to e-1
        for k in range(3, e):
            # x is root mod 2^k.
            # We want x' = x + t * 2^{k-1} mod 2^{k+1}
            # (x + t 2^{k-1})^2 = x^2 + t x 2^k + t^2 2^{2k-2}
            # Since k >= 3, 2k-2 >= k+1, so t^2 term vanishes mod 2^{k+1}
            # We need x^2 + t x 2^k = a mod 2^{k+1}
            # t x 2^k = a - x^2 mod 2^{k+1}
            # t x = (a - x^2) / 2^k mod 2
            # Since x is odd, x^{-1} mod 2 is 1.
            # t = (a - x^2) / 2^k mod 2

            diff = (a - x * x) >> k
            t = diff & 1
            x += t << (k - 1)

        # Now x is a root mod 2^e.
        # The roots come in 4 pairs: x, -x, x+2^{e-1}, -x+2^{e-1}
        n = 1 << e
        r1 = x
        r2 = n - x
        r3 = (x + (1 << (e - 1))) % n
        r4 = (n - x + (1 << (e - 1))) % n

        return sorted({r1, r2, r3, r4})
    else:
        # a is even
        if a == 0:
            # x^2 = 0 mod 2^e => x is multiple of 2^{ceil(e/2)}
            limit = 1 << ((e + 1) // 2)
            return list(range(0, 1 << e, limit))

        # a = 2^k * u where u is odd
        k = 0
        temp = a
        while temp % 2 == 0:
            k += 1
            temp //= 2

        if k % 2 != 0:
            return []

        if k >= e:
            # a is 0 mod 2^e, handled above
            limit = 1 << ((e + 1) // 2)
            return list(range(0, 1 << e, limit))

        # k < e and k is even
        j = k // 2
        rem_e = e - k
        u = temp # a / 2^k

        # Solve y^2 = u mod 2^rem_e
        # u is odd
        roots_y = _solve_mod_2pow(u, rem_e)
        if not roots_y:
            return []

        shift = 1 << j
        res = []

        # For each root y modulo 2^rem_e, we get 2^j roots modulo 2^e
        # x = y * 2^j + t * 2^{e - k + j} for t in 0..2^j - 1
        # Note: e - k + j = e - k + k/2 = e - k/2
        step = 1 << (e - k + j)

        for r in roots_y:
            base = (r * shift) % (1 << e)
            # Generate lifts
            for t in range(1 << j):
                res.append((base + t * step) % (1 << e))

        return sorted(list(set(res)))

def _solve_mod_odd_prime_power(a: int, p: int, e: int) -> list[int]:
    """Solves x^2 = a (mod p^e) for odd prime p"""
    n = p ** e

    # Handle a = 0 separately to avoid infinite loop in valuation
    if a == 0:
        # x^2 = 0 mod p^e => x is multiple of p^ceil(e/2)
        limit = p ** ((e + 1) // 2)
        return list(range(0, p**e, limit))

    # Check if a is divisible by p
    if a % p == 0:
        # a = p^k * u with p not dividing u
        k = 0
        temp = a
        while temp % p == 0:
            k += 1
            temp //= p
        u = temp

        if k % 2 != 0:
            return []

        half_k = k // 2
        rem_e = e - k

        if rem_e <= 0:
            # This case is covered by a=0 check, but just in case
            limit = p ** ((e + 1) // 2)
            return list(range(0, p**e, limit))

        # Recursive step to solve y^2 = u mod p^rem_e
        # u is coprime to p
        roots_y = _solve_mod_odd_prime_power(u, p, rem_e)
        if not roots_y:
            return []

        shift = p ** half_k
        res = []

        # For each root y modulo p^rem_e, we get p^half_k roots modulo p^e
        # x = y * p^half_k + t * p^(e - half_k) for t in 0..p^half_k - 1
        # Note: e - k + half_k = e - k + k/2 = e - k/2 = e - half_k
        step = p ** (e - half_k)

        for r in roots_y:
            base = (r * shift) % (p**e)
            # Generate lifts
            # We need p^half_k roots.
            # The step size is p^(e - half_k).
            # The number of steps is p^e / p^(e - half_k) = p^half_k.
            for t in range(p ** half_k):
                res.append((base + t * step) % (p**e))

        return sorted(list(set(res)))

    # a is coprime to p
    # Solve x^2 = a mod p using Tonelli-Shanks
    roots_p = tonelli_shanks(a, p)
    if not roots_p:
        return []

    # Lift roots to mod p^e
    all_roots = []
    for r in roots_p:
        roots_lifted = hensel_lift(r, a, p, e)
        all_roots.extend(roots_lifted)

    return sorted(all_roots)

def tonelli_shanks(n: int, p: int) -> list[int]:
    """Returns list of solutions to x^2 = n mod p, or empty list."""
    n = n % p
    if n == 0:
        return [0]
    if p == 2:
        return [n]

    # Check Legendre symbol
    if pow(n, (p - 1) // 2, p) != 1:
        return []

    # Factor p-1 = Q * 2^S
    Q = p - 1
    S = 0
    while Q % 2 == 0:
        Q //= 2
        S += 1

    # Find quadratic non-residue z
    z = 2
    while pow(z, (p - 1) // 2, p) != p - 1:
        z += 1

    M = S
    c = pow(z, Q, p)
    t = pow(n, Q, p)
    R = pow(n, (Q + 1) // 2, p)

    while True:
        if t == 1:
            return [R, p - R]

        # Find smallest i, 0 < i < M, such that t^{2^i} = 1
        i = 1
        temp = t
        while i < M:
            temp = pow(temp, 2, p)
            if temp == 1:
                break
            i += 1

        if i == M:
            return []

        # b = c^{2^{M-i-1}}
        b = pow(c, 1 << (M - i - 1), p)
        M = i
        c = pow(b, 2, p)
        t = (t * c) % p
        R = (R * b) % p

def hensel_lift(x0: int, a: int, p: int, e: int) -> list[int]:
    """Lifts solution x0 of x^2 = a mod p to mod p^e"""
    x = x0
    # x is root mod p^1
    for k in range(1, e):
        # We have x^2 = a mod p^k
        # We want x_new = x + t * p^k mod p^{k+1}
        # (x + t p^k)^2 = x^2 + 2 x t p^k + t^2 p^{2k}
        # 2k >= k+1 for k >= 1.
        # So x^2 + 2 x t p^k = a mod p^{k+1}
        # 2 x t p^k = a - x^2 mod p^{k+1}
        # t = (a - x^2) / (2 x p^k) mod p

        # Compute numerator (a - x^2) / p^k
        num = (a - x * x) // (p ** k)

        # Denominator is 2*x mod p. Since x is root mod p, x != 0 mod p.
        inv_2x = pow((2 * x) % p, -1, p)
        t = (num * inv_2x) % p
        x += t * (p ** k)

    return [x % (p ** e)]

def hist_add(date: str, days: int, switch: str) -> str:
    def parse_date(s):
        parts = s.split('-')
        if len(parts) != 3:
            raise ValueError("Invalid date format")
        if len(parts[0]) != 4 or len(parts[1]) != 2 or len(parts[2]) != 2:
            raise ValueError("Invalid date format")
        if not parts[0].isdigit() or not parts[1].isdigit() or not parts[2].isdigit():
            raise ValueError("Invalid date format")
        y, m, d = int(parts[0]), int(parts[1]), int(parts[2])
        if y < 1 or y > 9999 or m < 1 or m > 12 or d < 1:
            raise ValueError("Invalid date")
        return y, m, d

    def is_leap_greg(y):
        return (y % 4 == 0 and y % 100 != 0) or (y % 400 == 0)

    def is_leap_jul(y):
        return y % 4 == 0

    def days_in_month_greg(y, m):
        return [31, 29 if is_leap_greg(y) else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][m - 1]

    def days_in_month_jul(y, m):
        return [31, 29 if is_leap_jul(y) else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][m - 1]

    def validate_date_greg(y, m, d):
        if m > 12 or d > days_in_month_greg(y, m):
            raise ValueError("Invalid Gregorian date")

    def validate_date_jul(y, m, d):
        if m > 12 or d > days_in_month_jul(y, m):
            raise ValueError("Invalid Julian date")

    def to_abs(y, m, d, is_greg):
        days = 365 * (y - 1)
        if is_greg:
            days += (y - 1) // 4 - (y - 1) // 100 + (y - 1) // 400
        else:
            days += (y - 1) // 4

        dim = [0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
        if is_greg and is_leap_greg(y):
            dim[2] = 29
        elif not is_greg and is_leap_jul(y):
            dim[2] = 29

        for i in range(1, m):
            days += dim[i]
        days += d
        return days

    def abs_to_gregorian(n):
        n -= 1
        g = n // 146097
        n %= 146097
        y = 400 * g
        c = n // 36524
        c = c - 1 if c == 4 else c
        n -= c * 36524
        y += 100 * c
        b = n // 1461
        n %= 1461
        y += 4 * b
        a = n // 365
        a = a - 1 if a == 4 else a
        n -= a * 365
        y += a
        m = (n * 5 + 2) // 153
        d = n - (m * 153 + 2) // 5 + 1
        if m < 10:
            m += 3
        else:
            m -= 9
        y += m // 10
        return y, m, d

    def abs_to_julian(n):
        n -= 1
        y = 4 * (n // 1461)
        n %= 1461
        if n == 1460:
            y += 3
            n = 365
        else:
            y += 4 * (n // 365)
            n %= 365
        y += n // 365
        n %= 365
        m = (n * 5 + 2) // 153
        d = n - (m * 153 + 2) // 5 + 1
        if m < 10:
            m += 3
        else:
            m -= 9
        y += m // 10
        return y, m, d

    # Parse and validate switch
    sy, sm, sd = parse_date(switch)
    validate_date_greg(sy, sm, sd)
    if not (1582 <= sy <= 1929 and (sy > 1582 or sm >= 10) and (sy < 1929 or sm <= 12)):
        raise ValueError("Switch date out of range")

    # Parse and validate date
    dy, dm, dd = parse_date(date)

    # Determine calendar for date
    if date >= switch:
        validate_date_greg(dy, dm, dd)
        date_is_greg = True
    else:
        validate_date_jul(dy, dm, dd)
        date_is_greg = False

    # Check gap
    switch_abs = to_abs(sy, sm, sd, True)
    date_abs = to_abs(dy, dm, dd, date_is_greg)

    if date_is_greg and date_abs < switch_abs:
        raise ValueError("Date in gap")
    if not date_is_greg and date_abs > switch_abs - 1:
        raise ValueError("Date in gap")

    # Target
    target_abs = date_abs + days
    min_abs = 1
    max_abs = to_abs(9999, 12, 31, True)
    if target_abs < min_abs or target_abs > max_abs:
        raise ValueError("Result out of year range")

    # Determine calendar for target
    target_is_greg = target_abs >= switch_abs

    # Convert back
    if target_is_greg:
        ty, tm, td = abs_to_gregorian(target_abs)
        validate_date_greg(ty, tm, td)
    else:
        ty, tm, td = abs_to_julian(target_abs)
        validate_date_jul(ty, tm, td)

    return f"{ty:04d}-{tm:02d}-{td:02d}"
